import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int depth_in,
    int height_in,
    int width_in,
    int depth_out,
    int height_out,
    int width_out,
    int kernel_d,
    int kernel_h,
    int kernel_w,
    int stride_d,
    int stride_h,
    int stride_w,
    int padding_d,
    int padding_h,
    int padding_w,
    int output_padding_d,
    int output_padding_h,
    int output_padding_w,
    int groups
) {
    int global_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (global_idx >= batch_size * out_channels * depth_out * height_out * width_out)
        return;

    int idx = global_idx;
    int w_out = idx % width_out;
    idx /= width_out;
    int h_out = idx % height_out;
    idx /= height_out;
    int d_out = idx % depth_out;
    idx /= depth_out;
    int out_ch = idx % out_channels;
    int batch = idx / out_channels;

    if (batch >= batch_size) return;

    int group = out_ch / (out_channels / groups);
    int out_ch_in_group = out_ch % (out_channels / groups);

    float sum = 0.0f;
    int in_ch_per_group = in_channels / groups;
    int in_ch_start = group * in_ch_per_group;

    for(int kd = 0; kd < kernel_d; ++kd) {
        for(int kh = 0; kh < kernel_h; ++kh) {
            for(int kw = 0; kw < kernel_w; ++kw) {
                int d_in = (d_out - kd + 2 * padding_d - output_padding_d) / stride_d + 1;
                if((d_out - kd + 2 * padding_d - output_padding_d) % stride_d != 0) continue;

                int h_in = (h_out - kh + 2 * padding_h - output_padding_h) / stride_h + 1;
                if((h_out - kh + 2 * padding_h - output_padding_h) % stride_h != 0) continue;

                int w_in = (w_out - kw + 2 * padding_w - output_padding_w) / stride_w + 1;
                if((w_out - kw + 2 * padding_w - output_padding_w) % stride_w != 0) continue;

                if(d_in < 0 || d_in >= depth_in || h_in < 0 || h_in >= height_in || w_in < 0 || w_in >= width_in)
                    continue;

                for(int in_ch = 0; in_ch < in_ch_per_group; ++in_ch) {
                    int input_idx = (((batch * in_channels + (in_ch_start + in_ch)) * depth_in + d_in) * height_in + h_in) * width_in + w_in;
                    float input_val = input[input_idx];

                    int weight_idx = ((((in_ch_start + in_ch) * (out_channels/groups) + out_ch_in_group) * kernel_d + kd) * kernel_h + kh) * kernel_w + kw;
                    sum += input_val * weight[weight_idx];
                }
            }
        }
    }

    if(bias) sum += bias[out_ch];
    int output_idx = (((batch * out_channels + out_ch) * depth_out + d_out) * height_out + h_out) * width_out + w_out;
    output[output_idx] = sum;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride_d,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_d,
    int64_t padding_h,
    int64_t padding_w,
    int64_t output_padding_d,
    int64_t output_padding_h,
    int64_t output_padding_w,
    int64_t groups
) {
    auto in_sizes = input.sizes();
    int batch_size = in_sizes[0];
    int in_channels = in_sizes[1];
    int depth_in = in_sizes[2];
    int height_in = in_sizes[3];
    int width_in = in_sizes[4];

    int kernel_d = weight.size(2);
    int kernel_h = weight.size(3);
    int kernel_w = weight.size(4);

    int depth_out = (depth_in - 1) * stride_d - 2 * padding_d + kernel_d + output_padding_d;
    int height_out = (height_in - 1) * stride_h - 2 * padding_h + kernel_h + output_padding_h;
    int width_out = (width_in - 1) * stride_w - 2 * padding_w + kernel_w + output_padding_w;

    auto output = torch::zeros({batch_size, weight.size(1)*groups, depth_out, height_out, width_out}, input.options());
    int num_elements = output.numel();

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.has_value() ? bias->data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        output.size(1),
        depth_in,
        height_in,
        width_in,
        depth_out,
        height_out,
        width_out,
        kernel_d,
        kernel_h,
        kernel_w,
        stride_d,
        stride_h,
        stride_w,
        padding_d,
        padding_h,
        padding_w,
        output_padding_d,
        output_padding_h,
        output_padding_w,
        groups
    );

    return output;
}
"""

conv_transpose3d_cpp_source = "torch::Tensor conv_transpose3d_cuda(torch::Tensor, torch::Tensor, c10::optional<torch::Tensor>, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t);"

conv_transpose3d = load_inline(
    name='conv_transpose3d',
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=['conv_transpose3d_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1,1,1), 
                 padding: tuple = (0,0,0), output_padding: tuple = (0,0,0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(
            in_channels,
            out_channels // groups,
            *kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.weight.contiguous()
        return conv_transpose3d.conv_transpose3d_cuda(
            x, weight, self.bias,
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.output_padding[0], self.output_padding[1], self.output_padding[2],
            self.groups
        )
